"""Deterministic PAM (Partitioning Around Medoids, Kaufman & Rousseeuw 1990).

The paper runs `cluster::pam(distance_matrix_1, k = 4)$clustering` on a
precomputed dissimilarity object with no seed (the build phase is
deterministic), so we port the classic two-phase algorithm:

  BUILD: pick the most central object (min total dissimilarity), then add the
         candidate maximising the greedy gain
              sum_i max(0, D(i, nearest medoid) - D(i, c)).
  SWAP:  repeatedly apply the (medoid h -> object c) swap with the lowest total
         cost  cost(medoids) = sum_i D(i, nearest medoid)  until no swap
         decreases the cost.

R's `pam(..., do.swap = TRUE)` uses exactly this build+swap scheme; ties are
broken by the first index, which makes the result deterministic for a fixed
distance matrix.
"""

from __future__ import annotations

import numpy as np


def build_phase(D: np.ndarray, k: int) -> list[int]:
    n = D.shape[0]
    medoids = [int(np.argmin(D.sum(axis=1)))]
    while len(medoids) < k:
        nearest = D[:, medoids].min(axis=1)
        best_gain, best_c = -np.inf, None
        for c in range(n):
            if c in medoids:
                continue
            gain = float(np.clip(nearest - D[:, c], 0.0, None).sum())
            if gain > best_gain + 1e-12:
                best_gain, best_c = gain, c
        if best_c is None:
            raise RuntimeError("build phase could not find a new candidate")
        medoids.append(int(best_c))
    return medoids


def assign(D: np.ndarray, medoids) -> np.ndarray:
    """Nearest-medoid labels (ties -> lowest medoid index, as in R's pam)."""
    return np.argmin(D[:, medoids], axis=1)


def swap_phase(D: np.ndarray, medoids, max_iter: int = 200):
    medoids = [int(m) for m in medoids]

    def cost(meds):
        return float(D[:, meds].min(axis=1).sum())

    current = cost(medoids)
    for _ in range(max_iter):
        best = None
        for hi in range(len(medoids)):
            for c in range(D.shape[0]):
                if c in medoids:
                    continue
                trial = list(medoids)
                trial[hi] = c
                tc = cost(trial)
                if tc < current - 1e-12 and (best is None or tc < best[0]):
                    best = (tc, hi, c)
        if best is None:
            break
        current, hi, c = best
        medoids[hi] = c
    return medoids, current


def pam(D: np.ndarray, k: int, do_swap: bool = True):
    """Return (labels, medoids, cost) for PAM with k clusters on distance matrix D."""
    D = np.asarray(D, dtype=np.float64)
    if D.shape[0] != D.shape[1]:
        raise ValueError("D must be a square dissimilarity matrix")
    if not np.allclose(D, D.T):
        raise ValueError("D must be symmetric")
    if not np.allclose(np.diag(D), 0.0):
        raise ValueError("D must have a zero diagonal")
    medoids = build_phase(D, k)
    if do_swap:
        medoids, cost = swap_phase(D, medoids)
    else:
        cost = float(D[:, medoids].min(axis=1).sum())
    labels = assign(D, medoids)
    return labels, medoids, cost

